            n_consonants += 1 
    if n_consonants == n:
        result.append(word)
return result

def find_tuples(test_list, K):
  res = [sub for sub in test_list if all(ele % K == 0 for ele in sub)]
  return res

def remove_odd(l):
    for i in l:
        if i % 2 != 0:
            l.remove(i)
    return l

import re  
regex = r'^[a-z]$|^([a-z]).*\1$'
def check_char(string): 
	if(re.search(regex, string)): 
		return "Valid" 
	else: 
		return "Invalid"

